document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("ph-form"),t=document.getElementById("ph-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("ph-h").value),o=parseFloat(document.getElementById("ph-oh").value);let d,i;if(!isNaN(n)&&n>0)d=-Math.log10(n),i=14-d;else{if(isNaN(o)||!(o>0))return t.textContent="Enter H⁺ or OH⁻ concentration (mol/L).",void 0;i=-Math.log10(o),d=14-i}let l=d<7?"Acidic":d>7?"Basic":"Neutral";t.innerHTML=`<b>pH:</b> ${d.toFixed(3)}<br><b>pOH:</b> ${i.toFixed(3)}<br><b>Solution type:</b> ${l}`})});